// notPublic are the address ranges a webhook may not be sent to: those of the sender's own network and its neighbours,
// and the ones no host uses on the public internet.
var notPublic = []netip.Prefix{
	netip.MustParsePrefix("0.0.0.0/8"),          // "this network"
	netip.MustParsePrefix("10.0.0.0/8"),         // private
	netip.MustParsePrefix("100.64.0.0/10"),      // carrier-grade NAT
	netip.MustParsePrefix("127.0.0.0/8"),        // loopback
	netip.MustParsePrefix("169.254.0.0/16"),     // link-local, including the cloud metadata address
	netip.MustParsePrefix("172.16.0.0/12"),      // private
	netip.MustParsePrefix("192.168.0.0/16"),     // private
	netip.MustParsePrefix("224.0.0.0/4"),        // multicast
	netip.MustParsePrefix("255.255.255.255/32"), // broadcast
	netip.MustParsePrefix("::/128"),             // unspecified
	netip.MustParsePrefix("::1/128"),            // loopback
	netip.MustParsePrefix("fc00::/7"),           // unique local (private)
	netip.MustParsePrefix("fe80::/10"),          // link-local
	netip.MustParsePrefix("ff00::/8"),           // multicast
}

// isPublic reports whether ip is a public address. An IPv4 address written as IPv6 is judged as the IPv4 address it holds.
func isPublic(ip netip.Addr) bool {
	ip = ip.WithZone("").Unmap()
	if !ip.IsValid() {
		return false
	}
	for _, p := range notPublic {
		if p.Contains(ip) {
			return false
		}
	}
	return true
}

// hostAddrs returns the addresses host stands for: host itself when it is an IP address, otherwise every address the
// Resolver finds for it.
func (s *Service) hostAddrs(ctx context.Context, host string) ([]netip.Addr, error) {
	if ip, err := netip.ParseAddr(host); err == nil {
		return []netip.Addr{ip}, nil
	}
	addrs, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil || len(addrs) == 0 {
		return nil, fmt.Errorf("the host %q does not resolve", host)
	}
	out := make([]netip.Addr, 0, len(addrs))
	for _, a := range addrs {
		ip, ok := netip.AddrFromSlice(a.IP)
		if !ok {
			return nil, fmt.Errorf("the host %q resolves to an invalid address", host)
		}
		out = append(out, ip)
	}
	return out, nil
}

// CheckURL checks a webhook URL before it is saved: an absolute https URL with a host and no user name or password, whose
// host is a public address or resolves only to public addresses.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Hostname() == "" || u.User != nil {
		return fmt.Errorf("%w: use an absolute https URL with a host and no user name or password", ErrInvalidURL)
	}
	host := u.Hostname()
	addrs, err := s.hostAddrs(ctx, host)
	if err != nil {
		return fmt.Errorf("%w: %w", ErrInvalidURL, err)
	}
	for _, a := range addrs {
		if !isPublic(a) {
			return fmt.Errorf("%w: the host %q resolves to %s, which is not public", ErrInvalidURL, host, a.WithZone(""))
		}
	}
	return nil
}

